import Mathlib

def MonotonePref (pref : ℝ × ℝ → ℝ × ℝ → Prop) : Prop :=
  ∀ x y, x.1 < y.1 → x.2 < y.2 → pref x y

import Mathlib

def LocallyNonsatiated (u : ℝ → ℝ) : Prop :=
  ∀ x : ℝ, ∀ ε > 0, ∃ y : ℝ, |y - x| < ε ∧ u y > u x

import Mathlib
open Topology

variable {n : ℕ}

/-- A preference relation on ℝⁿ (weak preference: x ≿ y) -/
def StronglyMonotone (pref : (Fin n → ℝ) → (Fin n → ℝ) → Prop) : Prop :=
  ∀ x y : Fin n → ℝ, (∀ i, x i ≤ y i) → x ≠ y → pref y x

import Mathlib

def lexPref (x y : ℝ × ℝ) : Prop :=
  x.1 > y.1 ∨ (x.1 = y.1 ∧ x.2 ≥ y.2)

import Mathlib

variable {X : Type*}

def indifferenceSet (pref : X → X → Prop) (x : X) : Set X :=
  {y | pref y x ∧ pref x y}

