-- We work in ℝ^L represented as Fin L → ℝ

variable {L : ℕ}

-- Budget set: {x ∈ ℝ^L_+ | p · x ≤ w}
def BudgetSet (p : Fin L → ℝ) (w : ℝ) : Set (Fin L → ℝ) :=
  {x | (∀ i, 0 ≤ x i) ∧ ∑ i, p i * x i ≤ w}

-- Walrasian demand: maximizers of u over the budget set

import Mathlib

open Finset BigOperators
open BigOperators

variable {L : ℕ}

abbrev Bundle (L : ℕ) := Fin L → ℝ

noncomputable def expenditure (p x : Bundle L) : ℝ :=
  ∑ i : Fin L, p i * x i

def hicksianDemand (p : Bundle L) (u : Bundle L → ℝ) (u_bar : ℝ) : Set (Bundle L) :=
  { x | (∀ i, 0 ≤ x i) ∧ u x ≥ u_bar ∧
    ∀ y, (∀ i, 0 ≤ y i) → u y ≥ u_bar → expenditure p x ≤ expenditure p y }

import Mathlib

noncomputable def HalfSpace {N : ℕ} (p : EuclideanSpace ℝ (Fin N)) (c : ℝ) : Set (EuclideanSpace ℝ (Fin N)) :=
  {x | @inner ℝ _ _ p x ≥ c}

noncomputable def Hyperplane {N : ℕ} (p : EuclideanSpace ℝ (Fin N)) (c : ℝ) : Set (EuclideanSpace ℝ (Fin N)) :=
  {x | @inner ℝ _ _ p x = c}
